import { useCallback, useEffect, useState } from 'react';
// prettier-ignore
export const useExpandable = ({
  defaultExpanded,
  onExpandedChange
}) => {
  const [expandedNodes, setExpandedNodes] = useState(defaultExpanded ?? []);
  useEffect(() => {
    if (defaultExpanded) {
      setExpandedNodes(defaultExpanded);
    }
  }, [defaultExpanded]);
  useEffect(() => {
    if (typeof onExpandedChange === 'function') {
      onExpandedChange(expandedNodes);
    }
  }, [expandedNodes, onExpandedChange]);
  const onToggle = useCallback((nodeId, isExpanded) => {
    setExpandedNodes(prevNodes => isExpanded ? prevNodes.filter(node => node !== nodeId) : [...prevNodes, nodeId]);
  }, []);
  return {
    expandedNodes,
    onToggle
  };
};